mapper.insert:
INSERT INTO SAVINGS_RATE (
    product_id, save_term, min_rate, max_rate, start_date, end_date
) VALUES (
             #{productId}, #{saveTerm}, #{minRate}, #{maxRate}, #{startDate}, #{endDate}
         )

mapper.select:
SELECT p.product_id AS productId, p.product_name AS productName, p.product_type AS productType, p.company_code AS companyCode, r.max_rate AS maxRate FROM SAVINGS_PRODUCT p JOIN SAVINGS_RATE r ON p.product_id = r.product_id WHERE p.status = 10 AND r.save_term = #{saveTerm}
AND #{monthlyAmount} >= p.min_amount
AND (p.max_amount IS NULL OR p.max_amount = 0 OR p.max_amount >= #{monthlyAmount}) ORDER BY r.max_rate DESC
